package com.ftk.tpip.release.domain.model;
import java.time.Instant;import java.util.Objects;import java.util.regex.Pattern;
public record DeploymentBundleAsset(Long id,String bundleCode,String bundleVersion,long workspaceId,long operationId,long bindingVersionId,String environmentCode,String manifestDocument,String artifactUri,String artifactChecksum,String compilerVersion,String runtimeCompatibility,String signatureMetadata,BundleLifecycleStatus lifecycleStatus,String publishedBy,Instant publishedAt,Instant createdAt){private static final Pattern SHA=Pattern.compile("^[a-f0-9]{64}$");public DeploymentBundleAsset{if(id!=null&&id<=0)throw new IllegalArgumentException("id must be positive");bundleCode=required(bundleCode,"bundleCode");bundleVersion=required(bundleVersion,"bundleVersion");if(workspaceId<=0||operationId<=0||bindingVersionId<=0)throw new IllegalArgumentException("bundle references must be positive");environmentCode=required(environmentCode,"environmentCode");manifestDocument=required(manifestDocument,"manifestDocument");artifactUri=required(artifactUri,"artifactUri");if(artifactChecksum==null||!SHA.matcher(artifactChecksum).matches())throw new IllegalArgumentException("invalid artifactChecksum");compilerVersion=required(compilerVersion,"compilerVersion");runtimeCompatibility=required(runtimeCompatibility,"runtimeCompatibility");signatureMetadata=signatureMetadata==null?"{}":signatureMetadata;Objects.requireNonNull(lifecycleStatus);if(lifecycleStatus==BundleLifecycleStatus.PUBLISHED&&(publishedBy==null||publishedAt==null))throw new IllegalArgumentException("published bundle requires publisher and timestamp");}private static String required(String v,String f){String x=Objects.requireNonNull(v,f+" must not be null").trim();if(x.isEmpty())throw new IllegalArgumentException(f+" must not be blank");return x;}}
